import type { FeedPost, FeedComment, ReactionType, PostScope } from '~/types/feed'

export function useFeed() {
  const supabase = useSupabaseClient()
  const user = useSupabaseUser()

  const posts = ref<FeedPost[]>([])
  const loading = ref(false)
  const loadingMore = ref(false)
  const error = ref<string | null>(null)
  const hasMore = ref(true)

  const PAGE_SIZE = 10

  async function fetchPosts(scope: PostScope = 'general', batchYear?: number, page: number = 1) {
    const isFirstPage = page === 1
    if (isFirstPage) loading.value = true
    else loadingMore.value = true

    error.value = null

    const from = (page - 1) * PAGE_SIZE
    const to = from + PAGE_SIZE - 1

    let query = supabase
      .from('feed_posts')
      .select(`
        *,
        author:alumni_profiles!author_id(full_name, display_name, avatar_url, batch_year, current_job_title, current_company)
      `)
      .eq('status', 'published')
      .eq('post_scope', scope)

    if (scope === 'batch' && batchYear) {
      query = query.eq('batch_year', batchYear)
    }

    query = query
      .order('is_pinned', { ascending: false })
      .order('created_at', { ascending: false })
      .range(from, to)

    const { data, error: fetchError } = await query

    if (fetchError) {
      error.value = fetchError.message
    }
    else {
      const newPosts = (data as FeedPost[]) || []
      hasMore.value = newPosts.length === PAGE_SIZE

      if (isFirstPage) {
        posts.value = newPosts
      }
      else {
        posts.value = [...posts.value, ...newPosts]
      }

      // Fetch my reactions for these posts
      if (user.value && newPosts.length > 0) {
        const postIds = newPosts.map(p => p.id)
        const { data: reactions } = await supabase
          .from('feed_reactions')
          .select('post_id, reaction_type')
          .eq('alumni_id', user.value.id)
          .in('post_id', postIds)

        if (reactions) {
          const reactionMap = new Map(reactions.map(r => [r.post_id, r.reaction_type]))
          posts.value = posts.value.map(p => ({
            ...p,
            my_reaction: (reactionMap.get(p.id) as ReactionType) || null,
          }))
        }
      }
    }

    loading.value = false
    loadingMore.value = false
    return posts.value
  }

  async function createPost(content: string, imageUrls: string[] = [], scope: PostScope = 'general', batchYear?: number) {
    if (!user.value) return { success: false, error: 'Not authenticated' }

    const { data, error: insertError } = await supabase
      .from('feed_posts')
      .insert({
        author_id: user.value.id,
        content,
        image_urls: imageUrls.length > 0 ? imageUrls : null,
        post_scope: scope,
        batch_year: batchYear || null,
      })
      .select(`
        *,
        author:alumni_profiles!author_id(full_name, display_name, avatar_url, batch_year, current_job_title, current_company)
      `)
      .single()

    if (insertError) {
      return { success: false, error: insertError.message }
    }

    // Prepend to feed
    posts.value = [data as FeedPost, ...posts.value]
    return { success: true, data: data as FeedPost }
  }

  async function toggleReaction(postId: number, reactionType: ReactionType) {
    if (!user.value) return { success: false, error: 'Not authenticated' }

    const post = posts.value.find(p => p.id === postId)
    const existingReaction = post?.my_reaction

    if (existingReaction === reactionType) {
      // Remove reaction
      const { error: deleteError } = await supabase
        .from('feed_reactions')
        .delete()
        .eq('post_id', postId)
        .eq('alumni_id', user.value.id)

      if (!deleteError && post) {
        post.my_reaction = null
        post.reaction_count = Math.max(0, post.reaction_count - 1)
      }
      return { success: !deleteError, error: deleteError?.message }
    }
    else {
      // Upsert reaction
      const { error: upsertError } = await supabase
        .from('feed_reactions')
        .upsert({
          post_id: postId,
          alumni_id: user.value.id,
          reaction_type: reactionType,
        }, { onConflict: 'post_id,alumni_id' })

      if (!upsertError && post) {
        if (!existingReaction) post.reaction_count += 1
        post.my_reaction = reactionType
      }
      return { success: !upsertError, error: upsertError?.message }
    }
  }

  async function fetchComments(postId: number): Promise<FeedComment[]> {
    const { data, error: fetchError } = await supabase
      .from('feed_comments')
      .select(`
        *,
        author:alumni_profiles!author_id(full_name, display_name, avatar_url)
      `)
      .eq('post_id', postId)
      .eq('status', 'published')
      .is('parent_comment_id', null)
      .order('created_at', { ascending: true })

    if (fetchError) return []
    return (data as FeedComment[]) || []
  }

  async function addComment(postId: number, content: string, parentCommentId?: number) {
    if (!user.value) return { success: false, error: 'Not authenticated' }

    const { data, error: insertError } = await supabase
      .from('feed_comments')
      .insert({
        post_id: postId,
        author_id: user.value.id,
        content,
        parent_comment_id: parentCommentId || null,
      })
      .select(`
        *,
        author:alumni_profiles!author_id(full_name, display_name, avatar_url)
      `)
      .single()

    if (!insertError) {
      const post = posts.value.find(p => p.id === postId)
      if (post) post.comment_count += 1
    }

    return { success: !insertError, data: data as FeedComment, error: insertError?.message }
  }

  async function removePost(postId: number, reason: string) {
    const user = useSupabaseUser()
    const { error: updateError } = await supabase
      .from('feed_posts')
      .update({
        status: 'removed',
        removed_by: user.value?.id,
        removal_reason: reason,
      })
      .eq('id', postId)

    if (!updateError) {
      posts.value = posts.value.filter(p => p.id !== postId)
    }

    return { success: !updateError, error: updateError?.message }
  }

  async function hidePost(postId: number) {
    const { error: updateError } = await supabase
      .from('feed_posts')
      .update({ status: 'hidden' })
      .eq('id', postId)

    if (!updateError) {
      const post = posts.value.find(p => p.id === postId)
      if (post) post.status = 'hidden'
    }

    return { success: !updateError, error: updateError?.message }
  }

  async function fetchAllForAdmin(page: number = 1, status?: string) {
    loading.value = true
    const from = (page - 1) * PAGE_SIZE
    const to = from + PAGE_SIZE - 1

    let query = supabase
      .from('feed_posts')
      .select(`
        *,
        author:alumni_profiles!author_id(full_name, display_name, avatar_url, batch_year)
      `)
      .order('created_at', { ascending: false })
      .range(from, to)

    if (status) query = query.eq('status', status)

    const { data, error: fetchError } = await query

    loading.value = false
    if (fetchError) return []
    return (data as FeedPost[]) || []
  }

  return {
    posts,
    loading,
    loadingMore,
    error,
    hasMore,
    fetchPosts,
    createPost,
    toggleReaction,
    fetchComments,
    addComment,
    removePost,
    hidePost,
    fetchAllForAdmin,
  }
}
<script setup lang="ts">
import type { FeedPost, ReactionType, FeedComment } from '~/types/feed'
import { formatRelativeTime } from '~/utils/formatters'
import { useAuthStore } from '~/stores/auth'

const props = defineProps<{
  post: FeedPost
  adminMode?: boolean
}>()

const emit = defineEmits<{
  removed: [id: number]
}>()

const { toggleReaction, fetchComments, addComment, removePost, hidePost } = useFeed()
const authStore = useAuthStore()
const toast = useToast()

const comments = ref<FeedComment[]>([])
const showComments = ref(false)
const loadingComments = ref(false)
const commentText = ref('')
const postingComment = ref(false)

const reactionEmojis: Record<ReactionType, string> = {
  like: '👍',
  love: '❤️',
  celebrate: '🎉',
  support: '🤝',
}

async function handleReaction(type: ReactionType) {
  await toggleReaction(props.post.id, type)
}

async function toggleComments() {
  showComments.value = !showComments.value
  if (showComments.value && comments.value.length === 0) {
    loadingComments.value = true
    comments.value = await fetchComments(props.post.id)
    loadingComments.value = false
  }
}

async function handleAddComment() {
  if (!commentText.value.trim()) return
  postingComment.value = true
  const result = await addComment(props.post.id, commentText.value.trim())
  if (result.success && result.data) {
    comments.value.push(result.data)
    commentText.value = ''
  }
  postingComment.value = false
}

async function handleRemove() {
  const reason = prompt('Reason for removal:')
  if (!reason) return
  const result = await removePost(props.post.id, reason)
  if (result.success) {
    emit('removed', props.post.id)
    toast.add({ severity: 'success', summary: 'Post removed', life: 2000 })
  }
}

async function handleHide() {
  const result = await hidePost(props.post.id)
  if (result.success) {
    toast.add({ severity: 'info', summary: 'Post hidden', life: 2000 })
  }
}
</script>

<template>
  <div class="bg-white border border-slate-200 rounded-xl overflow-hidden">
    <!-- Header -->
    <div class="p-4 flex items-start justify-between gap-3">
      <div class="flex items-start gap-3">
        <img
          v-if="post.author?.avatar_url"
          :src="post.author.avatar_url"
          class="w-9 h-9 rounded-full object-cover shrink-0"
          alt="Author"
        >
        <div
          v-else
          class="w-9 h-9 rounded-full bg-primary-100 flex items-center justify-center text-primary-700 font-medium text-sm shrink-0"
        >
          {{ post.author?.full_name?.charAt(0)?.toUpperCase() || '?' }}
        </div>
        <div>
          <NuxtLink
            :to="`/directory/${post.author_id}`"
            class="font-medium text-slate-900 hover:text-primary-600 text-sm"
          >
            {{ post.author?.display_name || post.author?.full_name }}
          </NuxtLink>
          <div class="flex items-center gap-1.5 mt-0.5">
            <p v-if="post.author?.current_job_title" class="text-xs text-slate-500">
              {{ post.author.current_job_title }}
              <span v-if="post.author.current_company"> · {{ post.author.current_company }}</span>
            </p>
          </div>
          <p class="text-xs text-slate-400">{{ formatRelativeTime(post.created_at) }}</p>
        </div>
      </div>

      <!-- Admin controls -->
      <div v-if="adminMode" class="flex gap-1 shrink-0">
        <button
          class="p-1.5 text-slate-400 hover:text-amber-500 hover:bg-amber-50 rounded-lg transition-colors text-xs"
          title="Hide post"
          @click="handleHide"
        >
          <i class="pi pi-eye-slash" />
        </button>
        <button
          class="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors text-xs"
          title="Remove post"
          @click="handleRemove"
        >
          <i class="pi pi-trash" />
        </button>
      </div>
    </div>

    <!-- Content -->
    <div class="px-4 pb-3">
      <p class="text-sm text-slate-800 whitespace-pre-line leading-relaxed">{{ post.content }}</p>

      <!-- Images -->
      <div
        v-if="post.image_urls && post.image_urls.length > 0"
        class="mt-3 grid gap-2"
        :class="post.image_urls.length === 1 ? 'grid-cols-1' : 'grid-cols-2'"
      >
        <img
          v-for="(img, idx) in post.image_urls"
          :key="idx"
          :src="img"
          class="rounded-lg w-full object-cover max-h-64"
          alt="Post image"
        >
      </div>
    </div>

    <!-- Reactions bar -->
    <div class="px-4 pb-3 flex items-center justify-between">
      <div class="flex items-center gap-1">
        <button
          v-for="(emoji, type) in reactionEmojis"
          :key="type"
          class="flex items-center gap-1 px-2 py-1 rounded-lg text-sm transition-all"
          :class="[
            post.my_reaction === type
              ? 'bg-primary-50 text-primary-700'
              : 'text-slate-500 hover:bg-slate-50',
          ]"
          @click="handleReaction(type as ReactionType)"
        >
          <span>{{ emoji }}</span>
        </button>
        <span v-if="post.reaction_count > 0" class="text-xs text-slate-400 ml-1">
          {{ post.reaction_count }}
        </span>
      </div>

      <button
        class="flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-700 transition-colors"
        @click="toggleComments"
      >
        <i class="pi pi-comment text-xs" />
        <span>{{ post.comment_count }}</span>
      </button>
    </div>

    <!-- Comments section -->
    <div v-if="showComments" class="border-t border-slate-100 px-4 py-3 space-y-3">
      <div v-if="loadingComments" class="text-sm text-slate-400 text-center py-2">
        Loading comments...
      </div>

      <div
        v-for="comment in comments"
        :key="comment.id"
        class="flex gap-2"
      >
        <div class="w-7 h-7 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 text-xs font-medium shrink-0">
          {{ comment.author?.full_name?.charAt(0)?.toUpperCase() || '?' }}
        </div>
        <div class="flex-1 bg-slate-50 rounded-xl px-3 py-2">
          <p class="text-xs font-medium text-slate-700">
            {{ comment.author?.display_name || comment.author?.full_name }}
          </p>
          <p class="text-sm text-slate-700 mt-0.5">{{ comment.content }}</p>
        </div>
      </div>

      <!-- Comment input -->
      <div class="flex gap-2">
        <div class="w-7 h-7 rounded-full bg-primary-100 flex items-center justify-center text-primary-700 text-xs font-medium shrink-0">
          {{ authStore.displayName.charAt(0).toUpperCase() }}
        </div>
        <div class="flex-1 flex gap-2">
          <input
            v-model="commentText"
            type="text"
            placeholder="Write a comment..."
            class="flex-1 text-sm border border-slate-200 rounded-xl px-3 py-1.5 focus:outline-none focus:border-primary-400"
            @keyup.enter="handleAddComment"
          >
          <button
            class="px-3 py-1.5 text-sm font-medium text-white bg-primary-600 hover:bg-primary-700 rounded-xl transition-colors disabled:opacity-50"
            :disabled="!commentText.trim() || postingComment"
            @click="handleAddComment"
          >
            <i v-if="postingComment" class="pi pi-spin pi-spinner" />
            <i v-else class="pi pi-send" />
          </button>
        </div>
      </div>
    </div>
  </div>
</template>
